    if len(s) % 2 != 0:
        return False
    match: dict[str, str] = {")": "(", "]": "[", "}": "{"}
    stack: list[str] = []
    for c in s:
        if c in "([{":
            stack.append(c)
        elif not stack or stack.pop() != match[c]:
            return False
    return not stack

